			text = [=[Vahlarriel Demonslayer es una elfa de la noche enviada desde {link:darnassus}Darnassus{/link} para encontrar a dos hijos perdidos de la Casa Malem, una familia de mercaderes cuyo padre teme lo peor. Los hermanos {link:tyranis-malem}Tyranis{/link} y {link:dalinda-malem}Dalinda{/link} cruzaron la {link:stonetalon-mountains}Sierra Espolón{/link} unas semanas antes y desaparecieron en {link:desolace}Desolace{/link}. Las órdenes de Vahlarriel llevan un segundo propósito, más discreto. A sus superiores les importa sobre todo Dalinda. A Tyranis hay que juzgarlo antes de traerlo a casa.]=],
		},
		{
			title = "Importancia",
			text = [=[La búsqueda de Vahlarriel revela hasta dónde llega el {link:burning-blade}Filo Ardiente{/link}, y cómo incluso un hijo de los {link:night-elves}elfos de la noche{/link} puede sentirse atraído por la magia que su pueblo prohíbe.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Pide noticias del carro de los Malem en el norte de {link:desolace}Desolace{/link}.
• Sigue las huellas hacia el sur hasta la {link:thunder-axe-fortress}Fortaleza del Hacha de Trueno{/link}.
• Informa a sus superiores de {link:darnassus}Darnassus{/link} de cada giro de la búsqueda.]=],
		},
	},
	chapters = {
		{
			title = "El carro vacío",
			hint = "Encuentre el carro de la Casa Malem en el norte de Desolace.",
			text = [=[El carro apareció destrozado. Lo habían alcanzado hechizos y hojas, la lucha había sido breve y no había ningún cuerpo cerca. A su lado había un colgante, y huellas que llevaban al sur, hacia el humo de un gran fuerte. Vahlarriel conocía el lugar por su fama. Era la guarida de orcos que se habían entregado a los demonios.]=],
		},
		{
			title = "El destino de los Malem",
			hint = [=[Saque a Dalinda Malem sana y salva de la Fortaleza del Hacha de Trueno.]=],
			text = [=[{link:dalinda-malem}Dalinda{/link} volvió a la {link:nijels-point}Punta de Nijel{/link} por su propio pie, y Vahlarriel lo tuvo por una misericordia. {link:tyranis-malem}Tyranis{/link} no volvió. Había buscado el favor de los sectarios que lo capturaron, y murió entre ellos. La vergüenza de sus decisiones viajaría a casa con su hermana, y solo ella tendría que cargar con ella ante su pueblo.]=],
		},
	},
	mentions = {
		{ text = "La búsqueda de Vahlarriel" },
		{ text = "La búsqueda de Vahlarriel, el colgante y las huellas" },
		{ text = "La búsqueda de Vahlarriel, la fortaleza" },
		{ text = "Regreso junto a Vahlarriel" },
	},
	bonds = {
		{ id = "dalinda-malem", name = "Dalinda Malem", note = "la noble a la que buscaba" },
		{ id = "tyranis-malem", name = "Tyranis Malem", note = "el noble al que le ordenaron juzgar" },
		{ id = "kreldig-ungor", name = "Kreldig Ungor", note = "comparte el campamento" },
	},
})

