Translate("esES", "centaur-pariah", {
	title = "Paria centauro",
	subtitle = "Exiliado de los clanes",
	found = "Vagando por el sur de Desolace",
	hint = [=[Busque al centauro proscrito que vaga solo por las colinas del sur.]=],
	allegiance = "Ninguna, expulsado por los clanes",
	aliases = { "el Paria" },
	sections = {
		{
			title = "Resumen",
			text = [=[El Paria centauro fue expulsado por su pueblo como hereje. Sigue creyendo aquello por lo que fue exiliado: que los clanes pueden forjarse en una sola gran tribu. Para empezar esa obra necesita a un forastero, alguien sin clan, dispuesto a pisar las salas sagradas de {red:maraudon}Maraudon{/red}, donde solo pueden entrar los centauros más devotos.]=],
		},
		{
			title = "Importancia",
			text = [=[En una tierra donde los clanes viven para matarse entre sí, el Paria es el único {link:centaurs}centauro{/link} que sueña con su unión. Ese sueño puede ser lo más peligroso de {link:desolace}Desolace{/link}, pues todos los demás pueblos esperan que los clanes nunca se unan.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Da instrucciones escritas a quienes están dispuestos a entrar en Maraudon por él.
• Se propone comenzar la gran tarea de unir a las tribus.]=],
		},
	},
	chapters = {
		{
			title = "Una gran tribu",
			hint = "Haga lo que el Paria le pide en las salas de Maraudon.",
			text = [=[El forastero entró en la tumba y volvió con lo que el Paria necesitaba. Él se alegró. Ahora, dijo, podía empezar la gran obra. Pagó a quien le había ayudado y esperó que, cuando volvieran a verse, fuera en términos muy distintos. Nadie puede decir aún cuáles serán esos términos.]=],
		},
	},
	mentions = {
		{ text = "Las instrucciones del Paria" },
	},
	bonds = {
		{ id = "uthek-the-wise", name = "Uthek la Sabia", note = "de un clan que él quiere unir" },
		{ id = "warug", name = "Warug", note = "de un clan que él quiere unir" },
	},
})

Translate("esES", "uthek-the-wise", {
