	sections = {
		{
			title = "Resumen",
			text = [=[Uthek la Sabia es una chamán del clan Gelkis, y habla por su pueblo ante los pocos forasteros que este tolera. Escucha a la tierra, y la tierra le responde: le dice cuándo se debilitan los Magram, dónde yace un cristal lejano y qué manos están mojadas con sangre Magram. Cree que la magia de la tierra es más fuerte que el poder de cualquier guerrero, y que los Gelkis gobernarán algún día {link:desolace}Desolace{/link}.]=],
		},
		{
			title = "Importancia",
			text = [=[Uthek es la voz de la fe de los centauros en Theradras. A través de ella, los Gelkis aceptan la ayuda de la {link:alliance}Alianza{/link} y de la {link:horde}Horda{/link} por igual, y a través de ella esos extraños se ven arrastrados a una guerra de clanes más antigua que sus propias naciones.]=],
